# 교육용 의사코드
def find_path(graph, starts, target):
    queue = [(node, [node]) for node in starts]
    visited = set()
    while queue:
        node, path = queue.pop(0)
        if node == target:
            return {'verdict': 'reachable', 'path': path}
        if node in visited:
            continue
        visited.add(node)
        for next_node in graph.get(node, []):
            queue.append((next_node, path + [next_node]))
    return {'verdict': 'unreachable', 'path': []}

